INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Christopher Nolan', NULL, 'christopher-nolan', 'Male', 'Directing', '1970-07-30', NULL, 'London, England, UK', 'Christopher Nolan CBE is an Academy Award-winning British-American film director, producer, and screenwriter. Known for his non-linear storytelling, practical special effects, and cinematic epics, he is regarded as one of the pre-eminent filmmakers of the 21st century. His films have grossed over $6 billion worldwide and won 18 Academy Awards, including Best Director and Best Picture for Oppenheimer (2023).', 'people/christopher-nolan.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Cillian Murphy', NULL, 'cillian-murphy', 'Male', 'Acting', '1976-05-25', NULL, 'Douglas, Cork, Ireland', 'Cillian Murphy is an acclaimed Irish actor. He gained widespread recognition for his portrayal of Tommy Shelby in the BBC period drama Peaky Blinders and his long-standing collaboration with director Christopher Nolan in 28 Days Later, The Dark Knight Trilogy, Inception, Dunkirk, and Oppenheimer, for which he won the Academy Award for Best Actor in 2024.', 'people/cillian-murphy.jpg', '{\"imdb\":\"nm0614165\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Robert Downey Jr.', NULL, 'robert-downey-jr', 'Male', 'Acting', '1965-04-04', NULL, 'New York City, New York, USA', 'Robert Downey Jr. is an Academy Award-winning American actor whose career has been characterized by critical and popular success. Globally celebrated as Tony Stark / Iron Man across ten films in the Marvel Cinematic Universe, he also headlined Sherlock Holmes and won the Academy Award for Best Supporting Actor for his role as Lewis Strauss in Christopher Nolan\'s Oppenheimer (2023).', 'people/robert-downey-jr.jpg', '{\"instagram\":\"robertdowneyjr\",\"twitter\":\"RobertDowneyJr\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
