INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Vince Gilligan', NULL, 'vince-gilligan', 'Male', 'Directing', '1967-02-10', NULL, 'Richmond, Virginia, USA', 'Vince Gilligan is an American writer, producer, and director best known as the creator, head writer, executive producer, and director of AMC\'s prestige drama Breaking Bad (2008–2013) and its acclaimed spin-off prequel series Better Call Saul. He has won two Primetime Emmy Awards and six Writers Guild of America Awards.', 'people/vince-gilligan.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
