INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Leonardo DiCaprio', NULL, 'leonardo-dicaprio', 'Male', 'Acting', '1974-11-11', NULL, 'Los Angeles, California, USA', 'Leonardo DiCaprio is an Academy Award-winning American actor and film producer known for his intense, unconventional roles. He gained worldwide fame with Titanic (1997) and has collaborated frequently with Martin Scorsese, starring in Gangs of New York, The Aviator, The Departed, Inception, and The Wolf of Wall Street. He won the Oscar for Best Actor for The Revenant (2015).', 'people/leonardo-dicaprio.jpg', '{\"instagram\":\"leonardodicaprio\",\"twitter\":\"LeoDiCaprio\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Scarlett Johansson', NULL, 'scarlett-johansson', 'Female', 'Acting', '1984-11-22', NULL, 'New York City, New York, USA', 'Scarlett Johansson is an acclaimed American actress, the world\'s highest-paid actress in 2018 and 2019, and multiple Academy Award nominee. Her films have grossed over $15 billion worldwide. She is known for her breakout roles in Lost in Translation and Girl with a Pearl Earring, her defining role as Natasha Romanoff / Black Widow in the Marvel Cinematic Universe, and her performances in Marriage Story and Jojo Rabbit.', 'people/scarlett-johansson.jpg', '{\"imdb\":\"nm0424060\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Margot Robbie', NULL, 'margot-robbie', 'Female', 'Acting', '1990-07-02', NULL, 'Dalby, Queensland, Australia', 'Margot Robbie is an Australian actress and producer. Nominated for three Academy Awards and six BAFTA Awards, she rose to fame in Martin Scorsese\'s The Wolf of Wall Street. As co-founder of LuckyChap Entertainment, she produced and starred in I, Tonya, Promising Young Woman, and the global cultural phenomenon Barbie (2023).', 'people/margot-robbie.jpg', '{\"imdb\":\"nm3053338\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Tom Cruise', NULL, 'tom-cruise', 'Male', 'Acting', '1962-07-03', NULL, 'Syracuse, New York, USA', 'Tom Cruise is an American actor and producer. One of the world\'s highest-paid actors and cinema legends, his films have grossed over $12 billion worldwide. Celebrated for performing his own perilous stunts, he is known for the Mission: Impossible franchise, Top Gun, Top Gun: Maverick, Jerry Maguire, Rain Man, and Minority Report.', 'people/tom-cruise.jpg', '{\"twitter\":\"TomCruise\",\"instagram\":\"tomcruise\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
