INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Brad Pitt', NULL, 'brad-pitt', 'Male', 'Acting', '1963-12-18', NULL, 'Shawnee, Oklahoma, USA', 'Brad Pitt is an Academy Award-winning American actor and film producer. Known for compelling roles in Fight Club, Se7en, Ocean\'s Eleven, Inglourious Basterds, and Once Upon a Time in Hollywood (for which he won the Oscar for Best Supporting Actor), he has also produced Oscar-winning films including 12 Years a Slave and The Departed through Plan B Entertainment.', 'people/brad-pitt.jpg', '{\"imdb\":\"nm0000093\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Florence Pugh', NULL, 'florence-pugh', 'Female', 'Acting', '1996-01-03', NULL, 'Oxford, England, UK', 'Florence Pugh is an acclaimed English actress nominated for an Academy Award and two BAFTA Awards. She gained international praise for Lady Macbeth, Midsommar, and Greta Gerwig\'s Little Women. She portrayed Jean Tatlock in Christopher Nolan\'s Oppenheimer (2023), Yelena Belova in Black Widow, and Princess Irulan in Dune: Part Two.', 'people/florence-pugh.jpg', '{\"instagram\":\"florencepugh\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Shah Rukh Khan', NULL, 'shah-rukh-khan', 'Male', 'Acting', '1965-11-02', NULL, 'New Delhi, India', 'Shah Rukh Khan, often referred to as \"SRK\" and \"King Khan\", is an Indian actor, film producer, and television personality. Referred to in the media as the \"Baadshah of Bollywood\", he has appeared in more than 90 films and earned 14 Filmfare Awards. He is celebrated globally for iconic classics like Dilwale Dulhania Le Jayenge, Kabhi Khushi Kabhie Gham, Swades, Chak De! India, My Name Is Khan, and historic record-breaking blockbusters Pathaan and Jawan.', 'people/shah-rukh-khan.jpg', '{\"twitter\":\"iamsrk\",\"instagram\":\"iamsrk\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Deepika Padukone', NULL, 'deepika-padukone', 'Female', 'Acting', '1986-01-05', NULL, 'Copenhagen, Denmark', 'Deepika Padukone is one of the highest-paid actresses in India and a global cultural ambassador. She has received three Filmfare Awards and features in listings of the nation\'s most popular personalities. Known for critically acclaimed performances in Piku, Padmaavat, Bajirao Mastani, Yeh Jawaani Hai Deewani, and global blockbusters Jawan, Pathaan, and Kalki 2898 AD.', 'people/deepika-padukone.jpg', '{\"instagram\":\"deepikapadukone\",\"twitter\":\"deepikapadukone\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Amitabh Bachchan', NULL, 'amitabh-bachchan', 'Male', 'Acting', '1942-10-11', NULL, 'Prayagraj (Allahabad), Uttar Pradesh, India', 'Amitabh Bachchan is an Indian actor, film producer, television host, and former politician widely regarded as one of the most influential actors in the history of Indian and world cinema. Known as the \"Angry Young Man\" of Hindi cinema in the 1970s and 1980s, he has won four National Film Awards for Best Actor and 16 Filmfare Awards, starring in masterpieces like Sholay, Deewaar, Don, Agneepath, Black, Piku, and Kalki 2898 AD.', 'people/amitabh-bachchan.jpg', '{\"twitter\":\"SrBachchan\",\"instagram\":\"amitabhbachchan\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Priyanka Chopra Jonas', NULL, 'priyanka-chopra-jonas', 'Female', 'Acting', '1982-07-18', NULL, 'Jamshedpur, Bihar (now Jharkhand), India', 'Priyanka Chopra Jonas is an Indian actress, producer, and singer. Miss World 2000 pageant winner, she is one of India\'s highest-paid actresses and has received a National Film Award and five Filmfare Awards. She successfully transitioned to global Hollywood stardom as the lead in ABC\'s Quantico, Baywatch, The White Tiger, and the Amazon Prime global spy thriller Citadel.', 'people/priyanka-chopra-jonas.jpg', '{\"instagram\":\"priyankachopra\",\"twitter\":\"priyankachopra\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Aamir Khan', NULL, 'aamir-khan', 'Male', 'Acting', '1965-03-14', NULL, 'Mumbai, Maharashtra, India', 'Aamir Khan is an Indian actor, film director, and producer renowned as \"Mr. Perfectionist\" for his meticulous selection of socially relevant and transformative cinema. Recipient of nine Filmfare Awards and four National Film Awards, he headlined Oscar-nominated Lagaan (2001), Dil Chahta Hai, Rang De Basanti, Taare Zameen Par, 3 Idiots, PK, and Dangal (the highest-grossing Indian film of all time).', 'people/aamir-khan.jpg', '{\"imdb\":\"nm0451185\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Alia Bhatt', NULL, 'alia-bhatt', 'Female', 'Acting', '1993-03-15', NULL, 'Mumbai, Maharashtra, India', 'Alia Bhatt is a British-Indian actress known for her portrayals of women in challenging circumstances. She has received a National Film Award and six Filmfare Awards, making her one of the most accomplished actresses of modern cinema. Her defining roles include Highway, Udta Punjab, Raazi, Gully Boy, Gangubai Kathiawadi, Brahmāstra, and Netflix\'s Heart of Stone.', 'people/alia-bhatt.jpg', '{\"instagram\":\"aliaabhatt\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Hrithik Roshan', NULL, 'hrithik-roshan', 'Male', 'Acting', '1974-01-10', NULL, 'Mumbai, Maharashtra, India', 'Hrithik Roshan is an Indian actor acclaimed for his extraordinary dancing prowess, physique, and dramatic versatility. Winner of six Filmfare Awards, he became an overnight sensation with Kaho Naa... Pyaar Hai (2000), followed by memorable performances in Koi... Mil Gaya, the Krrish superhero series, Dhoom 2, Jodhaa Akbar, Guzaarish, Super 30, and high-octane blockbusters War and Fighter.', 'people/hrithik-roshan.jpg', '{\"twitter\":\"iHrithik\",\"instagram\":\"hrithikroshan\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Ranbir Kapoor', NULL, 'ranbir-kapoor', 'Male', 'Acting', '1982-09-28', NULL, 'Mumbai, Maharashtra, India', 'Ranbir Kapoor is an Indian actor who is one of the highest-paid actors of Hindi cinema and the recipient of seven Filmfare Awards. He is praised for his intense character portrayals and artistic bravery in films such as Rockstar, Barfi!, Wake Up Sid, Yeh Jawaani Hai Deewani, Tamasha, Sanju, Brahmāstra: Part One – Shiva, and the blockbuster smash Animal (2023).', 'people/ranbir-kapoor.jpg', '{\"imdb\":\"nm2467888\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Salman Khan', NULL, 'salman-khan', 'Male', 'Acting', '1965-12-27', NULL, 'Indore, Madhya Pradesh, India', 'Salman Khan is an Indian actor, film producer, and television personality affectionately known as \"Bhaijaan\". With a career spanning over three decades, he is one of the most commercially successful stars in world cinema. He has starred in cultural milestones including Hum Aapke Hain Koun..!, Andaz Apna Apna, Tere Naam, Dabangg, Ek Tha Tiger, Bajrangi Bhaijaan, and Sultan.', 'people/salman-khan.jpg', '{\"twitter\":\"BeingSalmanKhan\",\"instagram\":\"beingsalmankhan\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Kareena Kapoor Khan', NULL, 'kareena-kapoor-khan', 'Female', 'Acting', '1980-09-21', NULL, 'Mumbai, Maharashtra, India', 'Kareena Kapoor Khan is an Indian actress acclaimed for playing a variety of characters across a range of film genres. Winner of six Filmfare Awards, she defined pop culture with unforgettable roles as Poo in Kabhi Khushi Kabhie Gham and Geet in Jab We Met, followed by powerhouse performances in Chameli, Omkara, 3 Idiots, Udta Punjab, and Jaane Jaan.', 'people/kareena-kapoor-khan.jpg', '{\"instagram\":\"kareenakapoorkhan\"}', NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Steven Spielberg', NULL, 'steven-spielberg', 'Male', 'Directing', '1946-12-18', NULL, 'Cincinnati, Ohio, USA', 'Steven Spielberg is an American film director, producer, and screenwriter widely considered one of the most successful and influential filmmakers in cinematic history. Winner of three Academy Awards, he pioneered the modern Hollywood blockbuster with Jaws, E.T., Raiders of the Lost Ark, Jurassic Park, and masterpieces like Schindler\'s List and Saving Private Ryan.', 'people/steven-spielberg.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Martin Scorsese', NULL, 'martin-scorsese', 'Male', 'Directing', '1942-11-17', NULL, 'New York City, New York, USA', 'Martin Scorsese is an Academy Award-winning American film director, producer, and screenwriter. One of the major figures of the New Hollywood era, he is celebrated for intense psychological dramas, gritty character studies, and cinematic masterworks including Taxi Driver, Raging Bull, Goodfellas, Casino, The Departed, The Wolf of Wall Street, and Killers of the Flower Moon.', 'people/martin-scorsese.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Quentin Tarantino', NULL, 'quentin-tarantino', 'Male', 'Directing', '1963-03-27', NULL, 'Knoxville, Tennessee, USA', 'Quentin Tarantino is an Academy Award-winning American film director, screenwriter, and producer. Characterized by nonlinear storylines, satirical subject matter, sharp dialogue, and stylized violence, his iconic filmography includes Pulp Fiction, Reservoir Dogs, Kill Bill: Volume 1 & 2, Inglourious Basterds, Django Unchained, and Once Upon a Time in Hollywood.', 'people/quentin-tarantino.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('James Cameron', NULL, 'james-cameron', 'Male', 'Directing', '1954-08-16', NULL, 'Kapuskasing, Ontario, Canada', 'James Cameron is a Canadian filmmaker, ocean explorer, and technology pioneer. Renowned for creating groundbreaking science fiction and epic cinema, he directed three of the four highest-grossing films of all time: Titanic (1997), Avatar (2009), and Avatar: The Way of Water (2022), alongside sci-fi landmarks The Terminator and Aliens.', 'people/james-cameron.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Denis Villeneuve', NULL, 'denis-villeneuve', 'Male', 'Directing', '1967-10-03', NULL, 'Gentilly, Bécancour, Quebec, Canada', 'Denis Villeneuve is a critically acclaimed Canadian filmmaker known for his thought-provoking, atmospheric, and visually spectacular cinematic style. Nominated for four Academy Awards, he has directed acclaimed sci-fi epics and thrillers including Incendies, Prisoners, Sicario, Arrival, Blade Runner 2049, Dune (2021), and Dune: Part Two (2024).', 'people/denis-villeneuve.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Greta Gerwig', NULL, 'greta-gerwig', 'Female', 'Directing', '1983-08-04', NULL, 'Sacramento, California, USA', 'Greta Gerwig is an acclaimed American actress, screenwriter, and director. Nominated for four Academy Awards, she became the first solo female director to have a film gross over $1 billion with the global cultural phenomenon Barbie (2023), following her critically lauded auteur films Lady Bird (2017) and Little Women (2019).', 'people/greta-gerwig.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('David Fincher', NULL, 'david-fincher', 'Male', 'Directing', '1962-08-28', NULL, 'Denver, Colorado, USA', 'David Fincher is an American film director and executive producer celebrated for his meticulous psychological thrillers and precise visual craft. He has earned three Academy Award nominations for Best Director, directing enduring classics such as Se7en, Fight Club, Panic Room, Zodiac, The Curious Case of Benjamin Button, The Social Network, and Gone Girl.', 'people/david-fincher.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Emma Thomas', NULL, 'emma-thomas', 'Female', 'Production', '1971-12-09', NULL, 'London, England, UK', 'Emma Thomas DBE is an Academy Award-winning British film producer. Along with husband Christopher Nolan, she co-founded Syncopy Inc. and has produced every one of Nolan\'s feature films, including The Dark Knight Trilogy, Inception, Interstellar, Dunkirk, and Oppenheimer, for which she won the Academy Award for Best Picture in 2024.', 'people/emma-thomas.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Kevin Feige', NULL, 'kevin-feige', 'Male', 'Production', '1973-06-02', NULL, 'Boston, Massachusetts, USA', 'Kevin Feige is an American film and television producer who has been the president of Marvel Studios since 2007. The films he has produced have grossed a combined total of over $30 billion worldwide, making him the highest-grossing film producer in cinema history. He orchestrated the Marvel Cinematic Universe beginning with Iron Man (2008).', 'people/kevin-feige.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('S. S. Rajamouli', NULL, 's-s-rajamouli', 'Male', 'Directing', '1973-10-10', NULL, 'Amareshwara Camp, Karnataka, India', 'Koduri Srisaila Sri Rajamouli is an Indian film director and screenwriter revered globally for epic action spectacles and visual grandeur. The highest-grossing Indian director in cinema history, he directed Magadheera, Eega, the historic two-part Baahubali franchise, and global award-winning sensation RRR (2022), which won the Academy Award for Best Original Song.', 'people/s-s-rajamouli.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Sanjay Leela Bhansali', NULL, 'sanjay-leela-bhansali', 'Male', 'Directing', '1963-02-24', NULL, 'Mumbai, Maharashtra, India', 'Sanjay Leela Bhansali is an Indian film director, producer, screenwriter, and music composer known for his opulent sets, rich period aesthetics, operatic storytelling, and memorable musical compositions. Recipient of seven National Film Awards and twelve Filmfare Awards, his masterpieces include Hum Dil De Chuke Sanam, Devdas, Black, Goliyon Ki Raasleela Ram-Leela, Bajirao Mastani, Padmaavat, and Gangubai Kathiawadi.', 'people/sanjay-leela-bhansali.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Rajkumar Hirani', NULL, 'rajkumar-hirani', 'Male', 'Directing', '1962-11-20', NULL, 'Nagpur, Maharashtra, India', 'Rajkumar Hirani is an acclaimed Indian film director, screenwriter, and editor renowned for blending profound social themes with heartwarming humour and emotional depth. He has directed five universally acclaimed, record-breaking blockbusters: Munna Bhai M.B.B.S. (2003), Lage Raho Munna Bhai (2006), 3 Idiots (2009), PK (2014), and Sanju (2018).', 'people/rajkumar-hirani.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Karan Johar', NULL, 'karan-johar', 'Male', 'Directing', '1972-05-25', NULL, 'Mumbai, Maharashtra, India', 'Karan Johar is an Indian filmmaker and television host who heads Dharma Productions, one of the most prolific production houses in Indian cinema. Winner of two National Film Awards and six Filmfare Awards, he redefined romantic and family dramas with Kuch Kuch Hota Hai, Kabhi Khushi Kabhie Gham, My Name Is Khan, and produced blockbusters like Brahmāstra: Part One – Shiva and Rocky Aur Rani Kii Prem Kahaani.', 'people/karan-johar.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Siddharth Anand', NULL, 'siddharth-anand', 'Male', 'Directing', '1978-07-31', NULL, 'Mumbai, Maharashtra, India', 'Siddharth Anand is an Indian film director and producer acclaimed as the architect of high-octane modern Indian action cinema. He directed blockbuster milestones including Bachna Ae Haseeno, Bang Bang!, War (2019), the record-demolishing spy universe thriller Pathaan (2023) starring Shah Rukh Khan, and aerial action epic Fighter (2024).', 'people/siddharth-anand.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Atlee', NULL, 'atlee', 'Male', 'Directing', '1986-09-21', NULL, 'Madurai, Tamil Nadu, India', 'Arun Kumar, known mononymously as Atlee, is an Indian film director and screenwriter celebrated for high-voltage mass action entertainers with emotional resonance. After directing Tamil cinema blockbusters Theri, Mersal, and Bigil, he made his Hindi cinema debut with the colossal global blockbuster Jawan (2023), grossing over ₹1,150 crore worldwide.', 'people/atlee.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Aditya Chopra', NULL, 'aditya-chopra', 'Male', 'Directing', '1971-05-21', NULL, 'Mumbai, Maharashtra, India', 'Aditya Chopra is an Indian film director, studio executive, and screenwriter who serves as the chairman of Yash Raj Films (YRF). At age 23, he directed Dilwale Dulhania Le Jayenge (1995), the longest-running film in Indian cinema history. As producer, he masterminded the celebrated YRF Spy Universe spanning Ek Tha Tiger, War, Pathaan, and Tiger 3.', 'people/aditya-chopra.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Zoya Akhtar', NULL, 'zoya-akhtar', 'Female', 'Directing', '1972-10-14', NULL, 'Mumbai, Maharashtra, India', 'Zoya Akhtar is an acclaimed Indian film director and screenwriter celebrated for her nuanced, contemporary portrayals of human relationships and societal realities. Recipient of six Filmfare Awards, she directed cinematic milestones Luck by Chance, Zindagi Na Milegi Dobara (2011), Dil Dhadakne Do, Gully Boy (2019, India\'s official Oscar entry), and web series Made in Heaven.', 'people/zoya-akhtar.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Nitesh Tiwari', NULL, 'nitesh-tiwari', 'Male', 'Directing', '1973-05-15', NULL, 'Itarsi, Madhya Pradesh, India', 'Nitesh Tiwari is an Indian film director, screenwriter, and lyricist known for crafting uplifting, inspiring sports and social dramas. He directed the legendary sports biopic Dangal (2016) starring Aamir Khan, which grossed over $340 million worldwide and remains the highest-grossing Indian film of all time, as well as National Award-winner Chhichhore (2019).', 'people/nitesh-tiwari.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Sandeep Reddy Vanga', NULL, 'sandeep-reddy-vanga', 'Male', 'Directing', '1981-12-25', NULL, 'Warangal, Telangana, India', 'Sandeep Reddy Vanga is an Indian film director, screenwriter, and editor known for his raw, unapologetic, and intense filmmaking style. He burst into national prominence with Arjun Reddy (2017) and its Hindi remake Kabir Singh (2019), followed by the explosive, record-shattering global blockbuster Animal (2023) starring Ranbir Kapoor.', 'people/sandeep-reddy-vanga.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Gauri Khan', NULL, 'gauri-khan', 'Female', 'Production', '1970-10-08', NULL, 'New Delhi, India', 'Gauri Khan is an Indian film producer and interior designer. Co-chairperson of Red Chillies Entertainment alongside Shah Rukh Khan, she has produced some of the highest-grossing and culturally defining films of Hindi cinema, including Main Hoon Na, Om Shanti Om, My Name Is Khan, Ra.One, Chennai Express, Dear Zindagi, and global juggernaut Jawan (2023).', 'people/gauri-khan.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Dwayne Johnson', 'The Rock', 'dwayne-johnson', 'Male', 'Acting', '1972-05-02', NULL, 'Hayward, California, USA', 'Dwayne Douglas Johnson, also known by his ring name \"the Rock\", is an American actor and semi-retired professional wrestler. He is signed to WWE, where he performs on a part-time basis. Widely regarded as one of the greatest professional wrestlers of all time, Johnson was integral to the development and success of the World Wrestling Federation during the Attitude Era. He wrestled for the WWF full-time for eight years before pursuing an acting career. His films have grossed over $11.4 billion worldwide, making him one of the world\'s highest-grossing actors of all time. He is a co-owner of the United Football League, a member of the board of directors of TKO Group Holdings—the parent company of UFC and WWE—and co-founder of Seven Bucks Productions.', 'people/dwayne-johnson.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Chris Evans', NULL, 'chris-evans', 'Male', 'Acting', '1981-06-13', NULL, 'Boston, Massachusetts, USA', 'Christopher Robert Evans is an American actor. His films as a leading performer have grossed $11.4 billion worldwide, making him one of the highest-grossing film stars of all time and one of the world\'s highest-paid actors. His accolades include nominations for two Critics\' Choice Awards and a Drama League Award.', 'people/chris-evans.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Chris Hemsworth', NULL, 'chris-hemsworth', 'Male', 'Acting', '1983-08-11', NULL, 'Melbourne, Victoria, Australia', 'Christopher Hemsworth is an Australian actor and film producer. His films as a leading man have grossed over $12.1 billion worldwide, making him one of the highest-grossing film stars of all time. Hemsworth was one of the world\'s highest-paid actors annually from 2017 to 2019.', 'people/chris-hemsworth.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Henry Cavill', NULL, 'henry-cavill', 'Male', 'Acting', '1983-05-05', NULL, 'Saint Helier, Jersey, Channel Islands', 'Henry William Dalgliesh Cavill is a British actor. He gained wide recognition for portraying Superman in the DC Extended Universe (2013–2023), beginning with the film Man of Steel (2013) and reprising the role in Batman v Superman: Dawn of Justice (2016), Justice League (2017), and Black Adam (2022).', 'people/henry-cavill.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Tom Holland', NULL, 'tom-holland', 'Male', 'Acting', '1996-06-01', NULL, 'Kingston upon Thames, London, England', 'Thomas Stanley Holland is a British actor. His accolades include a BAFTA Award as well as two Critics\' Choice Awards nominations. He is the highest-grossing lead actor of all time.', 'people/tom-holland.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Robert Pattinson', NULL, 'robert-pattinson', 'Male', 'Acting', '1986-05-13', NULL, 'London, England, UK', 'Robert Douglas Thomas Pattinson is an English actor and producer. He is known for starring in both major studio productions and independent films, in which he often portrays eccentric characters across a diverse range of genres. Pattinson has been included on yearly lists of the world\'s highest-paid actors. In 2010, Time included him in its list of the 100 most influential people in the world, and he was also featured in the Forbes Celebrity 100.', 'people/robert-pattinson.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Jake Gyllenhaal', NULL, 'jake-gyllenhaal', 'Male', 'Acting', '1980-12-19', NULL, 'Los Angeles, California, USA', 'Jacob Benjamin Gyllenhaal is an American actor. Known for his performances on screen and stage, he has received numerous accolades, including a BAFTA Award, as well as nominations for an Academy Award, three Golden Globe Awards, three Tony Awards, and a Primetime Emmy Award. Born into the Gyllenhaal family, he is the son of film director Stephen Gyllenhaal and screenwriter Naomi Foner, and the younger brother of actress Maggie Gyllenhaal.', 'people/jake-gyllenhaal.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Benedict Cumberbatch', NULL, 'benedict-cumberbatch', 'Male', 'Acting', '1976-07-19', NULL, 'Hammersmith, London, England', 'Benedict Timothy Carlton Cumberbatch is an English actor. He has received various accolades, including a British Academy Television Award, a Primetime Emmy Award and a Laurence Olivier Award, in addition to nominations for two Academy Awards, two British Academy Film Awards, and four Golden Globes. In 2014, Time magazine named him one of the 100 most influential people in the world, and in 2015, he was appointed a CBE for services to performing arts and charity.', 'people/benedict-cumberbatch.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Mark Wahlberg', NULL, 'mark-wahlberg', 'Male', 'Acting', '1971-06-05', NULL, 'Dorchester, Boston, Massachusetts, USA', 'Mark Robert Michael Wahlberg, formerly known by his stage name Marky Mark, is an American actor, producer, and former rapper. His work as a leading man spans the comedy, drama, and action genres. He has received multiple accolades, including a BAFTA TV Award and a Sports Emmy Award, and nominations for two Academy Awards, three Golden Globes, and nine Primetime Emmy Awards.', 'people/mark-wahlberg.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Jason Statham', NULL, 'jason-statham', 'Male', 'Acting', '1967-07-26', NULL, 'Shirebrook, Derbyshire, England', 'Jason Statham is an English actor. He is known for being typecast as tough, gritty, or violent characters in action thriller films, and has been credited for leading the resurgence of action films during the 2000s and 2010s. By 2017, his films had grossed over £1.1 billion, making him one of the industry\'s most bankable stars. Films in which he has appeared have grossed over $6.25 billion worldwide.', 'people/jason-statham.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Sylvester Stallone', 'Sly Stallone', 'sylvester-stallone', 'Male', 'Acting', '1946-07-06', NULL, 'Hell\'s Kitchen, New York City, USA', 'Sylvester Gardenzio Stallone is an American actor and filmmaker. Known for his raw portrayals of vulnerable, working-class characters, he is considered a leading actor of the 1980s. Stallone has earned numerous accolades over a 58-year career, including a Golden Globe Award and a Critics\' Choice Award, and has been nominated for three Academy Awards and two BAFTA Awards. He is also, along with Harrison Ford, one of two actors in history to have starred in a box office number-one film across six consecutive decades. Films in which Stallone has appeared have grossed over $7.5 billion worldwide.', 'people/sylvester-stallone.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Nicolas Cage', NULL, 'nicolas-cage', 'Male', 'Acting', '1964-01-07', NULL, 'Long Beach, California, USA', 'Nicolas Cage is an American actor and film producer. He is the recipient of various accolades, including an Academy Award, a Screen Actors Guild Award, and a Golden Globe Award as well as nominations for two BAFTA Awards. Known for his versatility as an actor, Cage\'s work across diverse film genres has gained him a significant cult following.', 'people/nicolas-cage.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Gary Oldman', NULL, 'gary-oldman', 'Male', 'Acting', '1958-03-21', NULL, 'New Cross, London, England', 'Sir Gary Leonard Oldman is an English actor and filmmaker. Known for his versatility and intense acting style, he has received various accolades, including an Academy Award, a Golden Globe Award and three BAFTAs, as well as nominations for four Primetime Emmy Awards. His films have grossed over US$11 billion worldwide, making him one of the highest-grossing actors of all time.', 'people/gary-oldman.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Angelina Jolie', NULL, 'angelina-jolie', 'Female', 'Acting', '1975-06-04', NULL, 'Los Angeles, California, USA', 'Angelina Jolie is an American actress, filmmaker, and humanitarian. She is the recipient of numerous accolades, including an Academy Award, a Tony Award and three Golden Globe Awards. Films in which she has appeared have grossed over $6.9 billion worldwide. She has been named Hollywood\'s highest-paid actress multiple times.', 'people/angelina-jolie.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Sandra Bullock', NULL, 'sandra-bullock', 'Female', 'Acting', '1964-07-26', NULL, 'Arlington, Virginia, USA', 'Sandra Annette Bullock is an American actress and film producer. The world\'s highest-paid actress of 2010 and 2014, Bullock\'s filmography spans both comedy and drama, and her accolades include an Academy Award, a Golden Globe Award, two Screen Actors Guild Awards, and three Critics\' Choice Movie Awards. She was named one of Time\'s 100 most influential people in the world in 2010.', 'people/sandra-bullock.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Julia Roberts', NULL, 'julia-roberts', 'Female', 'Acting', '1967-10-28', NULL, 'Smyrna, Georgia, USA', 'Julia Fiona Roberts is an American actress. Known for her leading roles across several genres, she has received various accolades, including an Academy Award, a British Academy Film Award, and three Golden Globes. She became known for playing charming and relatable characters in romantic comedies and blockbusters, before expanding into dramas, thrillers, and independent films.', 'people/julia-roberts.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
