INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Sydney Sweeney', NULL, 'sydney-sweeney', 'Female', 'Acting', '1997-09-12', NULL, 'Spokane, Washington, USA', 'Sydney Bernice Sweeney is an American actress. She gained early recognition for her roles in the series Everything Sucks!, The Handmaid\'s Tale, and Sharp Objects in 2018. She received wider acclaim for her performances in the drama series Euphoria (2019–2026) and the first season of the anthology series The White Lotus (2021), both of which earned her nominations for Primetime Emmy Awards.', 'people/sydney-sweeney.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Anya Taylor-Joy', NULL, 'anya-taylor-joy', 'Female', 'Acting', '1996-04-16', NULL, 'Miami, Florida, USA', 'Anya-Josephine Marie Taylor-Joy is an actress. Born in Miami, she grew up in Buenos Aires and London. She began pursuing an acting career at the age of 16. After a series of small television roles, her breakthrough came with a leading role in the horror film The Witch (2015). She had roles in the horror film Split (2016) and its sequel Glass (2019), the black comedy film Thoroughbreds (2017), and the television crime drama series Peaky Blinders (2019–2022). Taylor-Joy also played Emma Woodhouse in the period drama Emma (2020).', 'people/anya-taylor-joy.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Nicole Kidman', NULL, 'nicole-kidman', 'Female', 'Acting', '1967-06-20', NULL, 'Honolulu, Hawaii, USA', 'Nicole Mary Kidman is an Australian and American actress and producer. Known for her work in blockbusters and independent films across many genres, she has consistently ranked among the world\'s highest-paid actresses since the late 1990s. Her accolades include an Academy Award, an Actor Award, a British Academy Film Award, six Golden Globe Awards, two Primetime Emmy Awards, and a Volpi Cup.', 'people/nicole-kidman.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Emily Blunt', NULL, 'emily-blunt', 'Female', 'Acting', '1983-02-23', NULL, 'Wandsworth, London, England', 'Emily Olivia Laura Blunt is a British actress. She is the recipient of various accolades, including a Golden Globe Award and two Actor Awards, in addition to nominations for an Academy Award and four British Academy Film Awards. Forbes ranked her as one of the highest-paid actresses in the world in 2020.', 'people/emily-blunt.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Zoe Saldana', NULL, 'zoe-saldana', 'Female', 'Acting', '1978-06-19', NULL, 'Passaic, New Jersey, USA', 'Zoë Yadira Saldaña-Perego, known professionally as Zoe Saldaña, is an American actress. The second highest grossing lead actor in history, she is the recipient of many accolades, including an Academy Award, a BAFTA Award, two Critics Choice Awards, a Golden Globe Award, a SAG Award, and a Cannes Film Festival Award. Time magazine named her one of the 100 most influential people in the world in 2023 and 2026.', 'people/zoe-saldana.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Tim Burton', NULL, 'tim-burton', 'Male', 'Directing', '1958-08-25', NULL, 'Burbank, California, USA', 'Timothy Walter Burton is an American filmmaker and former animator. He is known for pioneering Goth subculture in Hollywood, with his films employing a distinctive style that blends Gothic horror and dark fantasy aesthetics with whimsical and surreal elements. He has received numerous accolades, including one Emmy Award and nominations for two Academy Awards, a Golden Globe Award, and three BAFTA Awards. He was honored with the Venice International Film Festival\'s Golden Lion for Lifetime Achievement in 2007 and France\'s Order of Arts and Letters in 2010.', 'people/tim-burton.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
