INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Varun Dhawan', NULL, 'varun-dhawan', 'Male', 'Acting', '1987-04-24', NULL, 'Mumbai, Maharashtra, India', 'Varun Dhawan is one of Bollywood\'s most consistent box-office stars. Debuting in Student of the Year, he has delivered celebrated commercial and dramatic turns in Badlapur, October, Bhediya, Humpty Sharma Ki Dulhania, and Citadel: Honey Bunny.', 'people/varun-dhawan.jpg', NULL, NULL, 0, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
