INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('John Abraham', NULL, 'john-abraham', 'Male', 'Acting', '1972-12-17', NULL, 'Mumbai, Maharashtra, India', 'John Abraham is an Indian actor and film producer who works in Hindi films. He is a recipient of one National Film Award along with four Filmfare Awards nominations. Abraham has appeared in Forbes India\'s Celebrity 100 list since 2017.', 'people/john-abraham.jpg', NULL, NULL, 0, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Anil Kapoor', NULL, 'anil-kapoor', 'Male', 'Acting', '1956-12-24', NULL, 'Chembur, Mumbai, India', 'Anil Surinder Kapoor is an Indian actor and producer who works primarily in Hindi films, in addition to Indian television and international films. In a career spanning over 40 years, Kapoor has appeared in more than 100 films. He has received several accolades, including two National Film Awards and seven Filmfare Awards.', 'people/anil-kapoor.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Sanjay Dutt', NULL, 'sanjay-dutt', 'Male', 'Acting', '1959-07-29', NULL, 'Mumbai, Maharashtra, India', 'Sanjay Balraj Dutt is an Indian actor and film producer who works primarily in Hindi cinema, and has also appeared in some Telugu, Kannada, Tamil, Marathi and Punjabi films. He has acted in over 135 films. Known for his versatile roles, style, and intensity, he has often portrayed flawed heroes on screen. Dutt has received awards such as two Filmfare Awards, three Screen Awards and a Global Indian Film Award.', 'people/sanjay-dutt.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Bobby Deol', NULL, 'bobby-deol', 'Male', 'Acting', '1969-01-27', NULL, 'Mumbai, Maharashtra, India', 'Vijay Singh Deol, professionally known as Bobby Deol is an Indian actor who primarily works in Hindi cinema along with a few Tamil and Telugu films. In a career spanning more than three decades, Deol is known for portraying a range of unconventional roles in both films and OTT platforms. A member of the Deol family, he is the younger son of actor Dharmendra and the younger brother of actor Sunny Deol.', 'people/bobby-deol.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
