INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Mahesh Babu', 'Superstar Mahesh Babu', 'mahesh-babu', 'Male', 'Acting', '1975-08-09', NULL, 'Chennai, Tamil Nadu, India', 'Ghattamaneni Mahesh Babu is an Indian actor, producer and philanthropist, voice actor, who works in Telugu cinema. He is one of the highest-paid actors in Indian cinema and has been featured in Forbes India\'s Celebrity 100 list from 2012 to 2025. Referred to in the media as the Superstar, he appeared in over 30 films and has been a recipient of several accolades including, nine Nandi Awards, five Filmfare Awards South and four SIIMA Awards.', 'people/mahesh-babu.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Chiranjeevi', 'Megastar Chiranjeevi', 'chiranjeevi', 'Male', 'Acting', '1955-08-22', NULL, 'Mogalthur, Andhra Pradesh, India', 'Konidela Chiranjeevi is an Indian actor, philanthropist and former politician known for his work in Telugu cinema. Known as Mega Star, he is widely regarded as one of the most successful and influential actors in the history of Indian cinema. He is also celebrated as one of the finest dancers in Indian cinema. He has received numerous honours, including the Padma Bhushan in 2006 and the Padma Vibhushan in 2024 from the Government of India, as well as the IFFI Indian Film Personality of the Year Award in 2022. His other accolades include the Raghupathi Venkaiah Award, three Nandi Awards, and nine Filmfare Awards South, including the Lifetime Achievement Award and the Honorary Award. In 2013, CNN-IBN recognized him as one of \"the men who changed the face of the Indian Cinema\". In 2024, he was honoured with a Guinness World Record as the most prolific actor-dancer in the Indian film industry.', 'people/chiranjeevi.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Pawan Kalyan', 'Power Star', 'pawan-kalyan', 'Male', 'Acting', '1971-09-02', NULL, 'Bapatla, Andhra Pradesh, India', 'Konidela Pawan Kalyan is an Indian politician, actor, philanthropist, and martial artist serving as the 11th Deputy Chief Minister of Andhra Pradesh since June 2024. He also serves as the Minister for Panchayat Raj, Rural Development and Rural Water Supply; Environment, Forest, Science and Technology in the Government of Andhra Pradesh as MLA representing the Pithapuram constituency. He is the founder and president of the Janasena Party.', 'people/pawan-kalyan.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Nani', 'Natural Star Nani', 'nani', 'Male', 'Acting', '1984-02-24', NULL, 'Hyderabad, Telangana, India', 'Ghanta Naveen Babu, known professionally as Nani, is an Indian actor and producer who predominantly works in Telugu cinema. Nani is one of the highest-paid and most popular Telugu actors. He is a recipient of several accolades including two Nandi Awards, three Filmfare Awards South and four SIIMA Awards.', 'people/nani.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Vijay Deverakonda', NULL, 'vijay-deverakonda', 'Male', 'Acting', '1989-05-09', NULL, 'Achampet, Telangana, India', 'Deverakonda Vijay Sai, widely known as Vijay Deverakonda, is an Indian actor and film producer who works in Telugu films. Deverakonda is the recipient of a Filmfare Award, a Nandi Award and three SIIMA Awards.', 'people/vijay-deverakonda.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Ajith Kumar', 'Thala Ajith', 'ajith-kumar', 'Male', 'Acting', '1971-05-01', NULL, 'Secunderabad, Telangana, India', 'Ajith Kumar Subramaniam is an Indian actor who works predominantly in Tamil cinema. To date, he has starred in over 63 films, and won four Vijay Awards, three Cinema Express Awards, three Filmfare Awards South and three Tamil Nadu State Film Awards. In addition to his acting career, Ajith is an occasional racing driver and participated in the MRF Racing series (2010) and having competed in circuits around India in places such as Mumbai, Chennai and Delhi. He is one among very few Indians to race in the international arena and in Formula championships. Based on the annual earnings of Indian celebrities, he was included in the Forbes India Celebrity 100 list three times.', 'people/ajith-kumar.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Sivakarthikeyan', NULL, 'sivakarthikeyan', 'Male', 'Acting', '1985-02-17', NULL, 'Singampunari, Tamil Nadu, India', 'Sivakarthikeyan, also known by his initials as SK, is an Indian actor, playback singer, lyricist, and film producer primarily active in Tamil cinema. He served as a television presenter before his entry into films. He is a recipient of one Filmfare Award, two Tamil Nadu State Film Awards and eight SIIMA Awards.', 'people/sivakarthikeyan.jpg', NULL, NULL, 0, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Dulquer Salmaan', NULL, 'dulquer-salmaan', 'Male', 'Acting', '1986-07-28', NULL, 'Kochi, Kerala, India', 'Dulquer Salmaan is an Indian actor and producer who primarily works in Malayalam films, alongside a few Tamil, Telugu, and Hindi films. One of the highest paid Malayalam actors, Salmaan is a recipient of several awards including five Filmfare Awards South, one Kerala State Film Award, one Kerala Film Critics Association Award and one Telangana Gaddar Film Award.', 'people/dulquer-salmaan.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Sai Pallavi', NULL, 'sai-pallavi', 'Female', 'Acting', '1992-05-09', NULL, 'Kotagiri, Tamil Nadu, India', 'Sai Pallavi Senthamarai Kannan is an Indian actress who primarily works in Tamil and Telugu films. She has received several accolades, including a Tamil Nadu State Film Award, seven Filmfare Awards South, and three SIIMA Awards. One of South India\'s highest-paid actresses, she was featured in Forbes India \'s 2020 list of 30 Under 30. She was honoured with the Kalaimamani award by the Government of Tamil Nadu in 2021.', 'people/sai-pallavi.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Trisha Krishnan', NULL, 'trisha-krishnan', 'Female', 'Acting', '1983-05-04', NULL, 'Chennai, Tamil Nadu, India', 'Trisha Krishnan is an Indian actress known for her work primarily in Tamil and Telugu cinema. One of the highest-paid actresses in India, she has sustained a successful career as a leading actress for over two decades in Tamil cinema. Trisha gained prominence after winning the 1999 Miss Chennai pageant, which marked her entry into cinema. Often referred to as the \"Queen of South India\", she has received numerous accolades, including five Filmfare Awards South, a Tamil Nadu State Film Award and a Nandi Award.', 'people/trisha-krishnan.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Keerthy Suresh', NULL, 'keerthy-suresh', 'Female', 'Acting', '1992-10-17', NULL, 'Chennai, Tamil Nadu, India', 'Keerthy Suresh is an Indian actress who predominantly appears in Tamil, Telugu and Malayalam films. Her film accolades include one National Film Award, five SIIMA Awards, one Tamil Nadu State Film Award and two Filmfare Awards South. Keerthy was placed in Forbes India\'s 30 Under 30 list of 2021.', 'people/keerthy-suresh.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Jackie Chan', 'Jackie Chan', 'jackie-chan', 'Male', 'Acting', '1954-04-07', NULL, 'Victoria Peak, British Hong Kong', 'Chan Kong-sang, also known as Fang Shilong and known professionally as Jackie Chan and Sing Lung, is a Hong Kong martial artist, actor and filmmaker, known for his slapstick, acrobatic fighting style, comic timing, and innovative stunts, which he typically performs himself. With a film career spanning seven decades, he is regarded as one of the most iconic and influential martial artists in the history of cinema. Films in which he has appeared have grossed over $6 billion worldwide.', 'people/jackie-chan.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Michelle Yeoh', NULL, 'michelle-yeoh', 'Female', 'Acting', '1962-08-06', NULL, 'Ipoh, Perak, Malaysia', 'Michelle Yeoh Choo Kheng is a Malaysian actress. In a career spanning over four decades, she has acted in film and television productions covering a wide range of genres and received various accolades, including an Academy Award and a Golden Globe Award, along with nominations for two British Academy Film Awards. Credited as Michelle Khan in her early films, she rose to fame in the 1980s and 1990s after starring in Hong Kong action and martial arts films where she performed her own stunts. These roles included Yes, Madam (1985), Magnificent Warriors (1987), Police Story 3: Supercop (1992), The Heroic Trio and Tai Chi Master, and Wing Chun (1994).', 'people/michelle-yeoh.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Donnie Yen', NULL, 'donnie-yen', 'Male', 'Acting', '1963-07-27', NULL, 'Guangzhou, Guangdong, China', 'Donnie Yen Chi-tan is a Hong Kong actor, filmmaker, martial artist, and action director. His accolades include three Golden Horse Awards and five Hong Kong Film Awards. He is best known for portraying Wing Chun grandmaster Ip Man in the Ip Man film series, namely Ip Man (2008), Ip Man 2 (2010), Ip Man 3 (2015), and Ip Man 4: The Finale (2019). He also served as a co-producer of the spin-off Master Z: Ip Man Legacy (2018).', 'people/donnie-yen.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Lee Byung-hun', NULL, 'lee-byung-hun', 'Male', 'Acting', '1970-07-12', NULL, 'Seoul, South Korea', 'Lee Byung-hun is a South Korean actor. He has received acclaim for his work in a wide range of genres, most notably Joint Security Area (2000); A Bittersweet Life (2005); The Good, the Bad, the Weird (2008); I Saw the Devil (2010); Masquerade (2012); and the television series All In (2003), Iris (2009), Mr. Sunshine (2018), Our Blues (2022), and Squid Game (2021–2025). His other notable South Korean films include Inside Men (2015), Master (2016), Ashfall (2019), The Man Standing Next (2020), and No Other Choice (2025), for which he was nominated for a Golden Globe.', 'people/lee-byung-hun.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Ma Dong-seok', 'Don Lee', 'ma-dong-seok', 'Male', 'Acting', '1971-03-01', NULL, 'Seoul, South Korea', 'Lee Dong-seok, better known by the stage names Ma Dong-seok (마동석) and Don Lee, is a South Korean and American actor and film producer based in South Korea. He gained early recognition for his supporting roles in Nameless Gangster: Rules of the Time (2012) and The Neighbor (2012).', 'people/ma-dong-seok.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Gong Yoo', NULL, 'gong-yoo', 'Male', 'Acting', '1979-07-10', NULL, 'Busan, South Korea', 'Gong Ji-cheol, known professionally as Gong Yoo (공유), is a South Korean actor. He is known for his starring roles in the television series Coffee Prince (2007), Guardian: The Lonely and Great God (2016–2017), the Netflix series Squid Game (2021–2025), and the films Silenced (2011), The Suspect (2013), Train to Busan (2016), and The Age of Shadows (2016).', 'people/gong-yoo.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Hiroyuki Sanada', NULL, 'hiroyuki-sanada', 'Male', 'Acting', '1960-10-12', NULL, 'Shinagawa, Tokyo, Japan', 'Hiroyuki Sanada is a Japanese actor and martial artist. He has received numerous accolades, including a Golden Globe Award, two Primetime Emmy Awards, a British Academy Television Award, a Japan Academy Film Prize, two Hochi Film Awards, a Mainichi Film Award, three Blue Ribbon Awards for Best Actor, four Kinema Junpo Awards, and honors from the Yokohama Film Festival. In 2018, he received the Medal of Honor with Purple Ribbon from the Japanese government for his \"artistic developments, improvements, and accomplishments\", and in 2025, Time named him one of the 100 most influential people in the world.', 'people/hiroyuki-sanada.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Mads Mikkelsen', NULL, 'mads-mikkelsen', 'Male', 'Acting', '1965-11-22', NULL, 'Østerbro, Copenhagen, Denmark', 'Mads Dittmann Mikkelsen is a Danish actor. He rose to fame in Denmark as an actor for his roles such as Tonny in the first two films of the Pusher film trilogy, Detective Sergeant Allan Fischer in the television series Rejseholdet (2000–2004), Niels in Open Hearts (2002), Svend in The Green Butchers (2003), Ivan in Adam\'s Apples (2005) and Jacob Petersen in After the Wedding (2006).', 'people/mads-mikkelsen.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 04:54:48', '2026-10-29 04:54:48') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = VALUES(`is_featured`), `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
